($$cataratas-do-iguacu$$, $$Cataratas do Iguaçu$$, $$pontos$$, $$Uma das 7 Maravilhas da Natureza$$, $$Conjunto de 275 quedas d’água que se estende por quase 3 km na fronteira entre Brasil e Argentina, dentro do Parque Nacional do Iguaçu (Patrimônio Natural da Humanidade). As trilhas levam a mirantes com vista privilegiada da Garganta do Diabo.$$, ARRAY[$$https://images.unsplash.com/photo-1648510399328-b8981e9fc1bb?auto=format&fit=crop&w=1400&q=82$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Garganta_do_Diabo_-_Cataratas_do_Igua%C3%A7u.JPG/1280px-Garganta_do_Diabo_-_Cataratas_do_Igua%C3%A7u.JPG$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Passarela_de_Observa%C3%A7%C3%A3o_-_Cataratas_do_Igua%C3%A7u.JPG/1280px-Passarela_de_Observa%C3%A7%C3%A3o_-_Cataratas_do_Igua%C3%A7u.JPG$$, $$https://images.unsplash.com/photo-1541686826972-068336f11d45?auto=format&fit=crop&w=1400&q=82$$]::text[], $$Parque Nacional do Iguaçu$$, $$Rodovia BR-469, Km 18 — Foz do Iguaçu, PR$$, -25.6953, -54.4367, $$[{"label":"Todos os dias","value":"09:00 – 17:00"},{"label":"Bilheteria","value":"até 16:00"}]$$::jsonb, $$+55 45 3521-4400$$, null, $${"website":"cataratasdoiguacu.com.br","instagram":"@cataratasdoiguacu"}$$::jsonb, 4.9, 128430, 2, '{}'::text[], ARRAY[$$Ao ar livre$$, $$Família$$, $$Imperdível$$, $$Natureza$$]::text[], true, 24.5, $$A partir de R$ 100 (inteira) — meia-entrada e crianças até 2 anos gratuito$$, ARRAY[$$Ingresso inclui transporte no ônibus panorâmico dentro do parque.$$, $$Leve capa de chuva — na Garganta do Diabo você se molha.$$, $$Trilha principal: 1,2 km, acessível para cadeirantes.$$]::text[], $$A partir do centro, pegue a linha 120 (Parque Nacional) no Terminal de Transporte Urbano, ou vá de carro/app pela BR-469 (~25 min).$$, null, $$[{"author":"Marina S.","rating":5,"comment":"Simplesmente surreal. A Garganta do Diabo é indescritível!","date":"jul 2026"},{"author":"Diego R.","rating":5,"comment":"Vá cedo para pegar menos fila. Vale cada centavo.","date":"jun 2026"}]$$::jsonb),
($$marco-das-tres-fronteiras$$, $$Marco das Três Fronteiras$$, $$pontos$$, $$Onde Brasil, Argentina e Paraguai se encontram$$, $$Complexo turístico às margens do encontro dos rios Iguaçu e Paraná, com vista para os obeliscos dos três países. Ao entardecer, apresentação de dança e show de luzes contam a história da tríplice fronteira.$$, ARRAY[$$https://upload.wikimedia.org/wikipedia/commons/7/71/Marco_das_Tr%C3%AAs_Fronteiras_-_Foz_do_Igua%C3%A7u.jpg$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/Marcos_das_Tres_Fronteiras_-_Foz_do_Iguacu.jpg/1280px-Marcos_das_Tres_Fronteiras_-_Foz_do_Iguacu.jpg$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Marco_das_Tr%C3%AAs_Fronteiras.jpg/1280px-Marco_das_Tr%C3%AAs_Fronteiras.jpg$$]::text[], $$Jardim Eldorado$$, $$Av. General Meira, s/n — Foz do Iguaçu, PR$$, -25.5946, -54.5936, $$[{"label":"Ter – Dom","value":"14:00 – 22:00"}]$$::jsonb, $$+55 45 3527-1600$$, null, $${"instagram":"@marcodastresfronteiras"}$$::jsonb, 4.6, 21540, 2, '{}'::text[], ARRAY[$$Pôr do sol$$, $$Cultura$$, $$Show$$]::text[], true, 8.1, $$R$ 45 (inteira) / R$ 22,50 (meia)$$, ARRAY[$$O melhor horário é no fim da tarde para ver o pôr do sol.$$, $$Há praça de alimentação no local.$$]::text[], $$Cerca de 15 min de carro do centro pela Av. General Meira.$$, null, null),
($$parque-das-aves$$, $$Parque das Aves$$, $$pontos$$, $$Voe entre tucanos e araras na Mata Atlântica$$, $$Único parque do mundo focado em aves da Mata Atlântica. Viveiros imersivos permitem caminhar entre araras, tucanos e flamingos, além de conhecer o trabalho de conservação de espécies ameaçadas.$$, ARRAY[$$https://upload.wikimedia.org/wikipedia/commons/d/db/Arara_Vermelha_-_Parque_das_aves_-_Foz_do_Iguacu_-_Brasil_%2823982184550%29.jpg$$, $$https://upload.wikimedia.org/wikipedia/commons/3/30/Arara_Azul-_Parque_das_aves_-_Foz_do_Iguacu_-_Brasil_%2824251638006%29.jpg$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Tucano_parque_das_aves_foz.jpg/1280px-Tucano_parque_das_aves_foz.jpg$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/Parque_das_Aves.jpg/1280px-Parque_das_Aves.jpg$$]::text[], $$Vila Yolanda$$, $$Av. das Cataratas, Km 17,1 — Foz do Iguaçu, PR$$, -25.6188, -54.4832, $$[{"label":"Todos os dias","value":"08:30 – 17:00"}]$$::jsonb, $$+55 45 3529-8282$$, null, $${"website":"parquedasaves.com.br","instagram":"@parquedasaves"}$$::jsonb, 4.8, 47210, 2, '{}'::text[], ARRAY[$$Família$$, $$Natureza$$, $$Educativo$$]::text[], false, 23, $$R$ 85 (inteira) / R$ 42,50 (meia)$$, ARRAY[$$Fica ao lado da entrada das Cataratas — dá para combinar os dois no mesmo dia.$$]::text[], $$Mesma rota das Cataratas (BR-469), desça um ponto antes.$$, null, null),
($$usina-de-itaipu$$, $$Usina de Itaipu$$, $$pontos$$, $$A maior geradora de energia limpa do planeta$$, $$Visite uma das maiores hidrelétricas do mundo. O passeio panorâmico mostra a barragem e o vertedouro; a Iluminação de Itaipu, às sextas e sábados, ilumina a estrutura em um espetáculo à parte.$$, ARRAY[$$https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Barragem_de_Itaipu_%288155763889%29.jpg/1280px-Barragem_de_Itaipu_%288155763889%29.jpg$$, $$https://upload.wikimedia.org/wikipedia/commons/5/5e/Over_the_main_Dam_-_Sobre_a_barragem_principal_-_Itaipu_-_Foz_do_Iguacu_-_Brasil_%2824277757365%29.jpg$$, $$https://upload.wikimedia.org/wikipedia/commons/7/7b/Ilumina%C3%A7%C3%A3o_da_barragem_de_Itaipu_%288152312286%29.jpg$$]::text[], $$Itaipu$$, $$Av. Tancredo Neves, 6702 — Foz do Iguaçu, PR$$, -25.4083, -54.5889, $$[{"label":"Todos os dias","value":"08:00 – 16:00"}]$$::jsonb, $$+55 45 3520-6676$$, null, $${"website":"turismoitaipu.com.br"}$$::jsonb, 4.7, 33110, 2, '{}'::text[], ARRAY[$$Engenharia$$, $$Família$$, $$Educativo$$]::text[], false, 12.4, $$Passeio Panorâmico a partir de R$ 55$$, ARRAY[$$Leve documento com foto.$$, $$Reserve com antecedência em alta temporada.$$]::text[], $$Av. Tancredo Neves sentido norte, ~20 min do centro.$$, null, null),
($$bufalo-branco$$, $$Churrascaria Búfalo Branco$$, $$restaurantes$$, $$O maior rodízio de carnes de Foz$$, $$Tradicional churrascaria com rodízio de mais de 30 cortes, buffet de saladas e frutos do mar. Ambiente amplo e familiar, referência na cidade há mais de 30 anos.$$, ARRAY[$$https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=1080&q=70$$, $$https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1080&q=70$$, $$https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1080&q=70$$]::text[], $$Centro$$, $$Rua Rebouças, 530 — Centro, Foz do Iguaçu, PR$$, -25.5478, -54.5839, $$[{"label":"Almoço","value":"11:30 – 15:00"},{"label":"Jantar","value":"18:00 – 23:30"}]$$::jsonb, $$+55 45 3523-9744$$, $$5545999990001$$, $${"instagram":"@bufalobranco","website":"bufalobranco.com.br"}$$::jsonb, 4.7, 8920, 3, ARRAY[$$Dinheiro$$, $$Pix$$, $$Visa$$, $$Mastercard$$, $$Elo$$, $$American Express$$]::text[], ARRAY[$$Rodízio$$, $$Família$$, $$Frutos do mar$$]::text[], true, 1.2, null, '{}'::text[], null, $$[{"title":"Entradas","items":[{"name":"Tábua de frios","description":"Queijos, salames e azeitonas","price":62,"photo":"https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1080&q=70"},{"name":"Bolinho de mandioca","description":"Porção com 12 unidades","price":38,"photo":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1080&q=70"}]},{"title":"Pratos principais","items":[{"name":"Rodízio completo","description":"Mais de 30 cortes + buffet livre","price":149,"photo":"https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=1080&q=70"},{"name":"Picanha na chapa","description":"Acompanha arroz, farofa e vinagrete (serve 2)","price":168,"photo":"https://images.unsplash.com/photo-1600891964599-f61ba0e24092?auto=format&fit=crop&w=1080&q=70"}]},{"title":"Sobremesas","items":[{"name":"Petit gâteau","description":"Com sorvete de creme","price":34,"photo":"https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1080&q=70"},{"name":"Abacaxi grelhado","description":"Com canela e sorvete","price":28}]},{"title":"Bebidas","items":[{"name":"Caipirinha","description":"Limão, morango ou maracujá","price":26},{"name":"Suco natural","description":"Laranja, abacaxi ou maracujá","price":14}]}]$$::jsonb, $$[{"author":"Carlos M.","rating":5,"comment":"Carne no ponto e atendimento nota 10.","date":"ago 2026"},{"author":"Ana P.","rating":4,"comment":"Rodízio farto, só achei o salão um pouco cheio.","date":"jul 2026"}]$$::jsonb),
